<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { FolderKanban, LogOut, RefreshCw, Search, ShieldCheck, UserPlus, UserRoundCog, X } from 'lucide-vue-next'
import type { UserDto } from '../types'
import { showError, showSuccess } from '../composables/use-toast'
import { apiJson, apiResult, errorMessage } from '../utils/api-client'

interface AdminUser { id:string; fullName:string; email:string; role:'Admin'|'Moderator'|'Member'; isActive:boolean; avatarUrl?:string|null; createdAt:string; ownedProjectCount:number; membershipProjectCount:number }
interface UserProject { id:string; name:string; code:string; status:string; archivedAt?:string|null; isOwner:boolean; role:string; taskCount:number }
interface PagedUsers { items:AdminUser[]; page:number; pageSize:number; totalItems:number; totalPages:number }

const me=ref<UserDto|null>(null), users=ref<AdminUser[]>([]), selected=ref<AdminUser|null>(null), projects=ref<UserProject[]>([])
const loading=ref(true), saving=ref(false), projectsLoading=ref(false), createOpen=ref(false)
const search=ref(''), role=ref(''), status=ref(''), page=ref(1), totalItems=ref(0), totalPages=ref(1)
const form=ref({fullName:'',email:'',password:'',role:'Member'})
let searchTimer:ReturnType<typeof setTimeout>|undefined
const isAdmin=computed(()=>me.value?.role==='Admin')
const canEditSelected=computed(()=>selected.value?.role!=='Admin'&&!(me.value?.role==='Moderator'&&selected.value?.role==='Moderator'))

async function loadUsers(){loading.value=true;try{const p=new URLSearchParams({page:String(page.value),pageSize:'25'});if(search.value.trim())p.set('search',search.value.trim());if(role.value)p.set('role',role.value);if(status.value)p.set('isActive',status.value);const r=await apiJson<PagedUsers>(`/api/admin/users?${p}`);users.value=r.items;totalItems.value=r.totalItems;totalPages.value=Math.max(r.totalPages,1)}catch(e){showError(errorMessage(e,'Không thể tải danh sách người dùng.'))}finally{loading.value=false}}
async function selectUser(user:AdminUser){selected.value={...user};projects.value=[];projectsLoading.value=true;try{projects.value=await apiJson<UserProject[]>(`/api/admin/users/${user.id}/projects`)}catch(e){showError(errorMessage(e,'Không thể tải dự án của người dùng.'))}finally{projectsLoading.value=false}}
async function saveUser(){if(!selected.value||!canEditSelected.value)return;saving.value=true;try{const updated=await apiJson<AdminUser>(`/api/admin/users/${selected.value.id}`,{method:'PATCH',body:JSON.stringify({fullName:selected.value.fullName,role:selected.value.role,isActive:selected.value.isActive,avatarUrl:selected.value.avatarUrl})});selected.value=updated;showSuccess('Đã cập nhật người dùng.');await loadUsers()}catch(e){showError(errorMessage(e,'Không thể cập nhật người dùng.'))}finally{saving.value=false}}
async function createUser(){saving.value=true;try{await apiJson('/api/admin/users',{method:'POST',body:JSON.stringify({...form.value,isActive:true})});createOpen.value=false;form.value={fullName:'',email:'',password:'',role:'Member'};showSuccess('Đã tạo người dùng mới.');await loadUsers()}catch(e){showError(errorMessage(e,'Không thể tạo người dùng.'))}finally{saving.value=false}}
async function revokeSessions(){if(!selected.value)return;try{await apiJson(`/api/admin/users/${selected.value.id}/revoke-sessions`,{method:'POST'});showSuccess('Đã thu hồi các phiên đăng nhập.')}catch(e){showError(errorMessage(e,'Không thể thu hồi phiên đăng nhập.'))}}
async function transferAdmin(){if(!selected.value||selected.value.role!=='Moderator'||!confirm(`Chuyển quyền Admin duy nhất cho ${selected.value.fullName}? Bạn sẽ trở thành Moderator và cả hai tài khoản phải đăng nhập lại.`))return;saving.value=true;try{await apiJson('/api/admin/users/transfer-admin',{method:'POST',body:JSON.stringify({successorUserId:selected.value.id})});window.location.href='/Account/Login'}catch(e){showError(errorMessage(e,'Không thể chuyển giao quyền Admin.'));saving.value=false}}
async function updateProjectRole(project:UserProject,nextRole:string){try{await apiJson(`/api/admin/users/${selected.value!.id}/projects/${project.id}`,{method:'PATCH',body:JSON.stringify({role:nextRole})});project.role=nextRole;showSuccess('Đã cập nhật vai trò dự án.')}catch(e){showError(errorMessage(e,'Không thể cập nhật vai trò dự án.'))}}
function dateLabel(value:string){return new Intl.DateTimeFormat('vi-VN',{dateStyle:'medium'}).format(new Date(value))}
watch([role,status],()=>{page.value=1;void loadUsers()});watch(page,()=>void loadUsers());watch(search,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=1;void loadUsers()},300)})
onMounted(async()=>{try{me.value=await apiResult<UserDto>('/api/auth/me');await loadUsers()}catch(e){showError(errorMessage(e,'Bạn không có quyền truy cập trang quản trị.'))}})
</script>

<template>
  <div class="admin-page">
    <header class="page-head">
      <div><span class="kicker"><ShieldCheck :size="16"/> Kiểm soát truy cập</span><h1>Quản lý người dùng</h1><p>Quản lý tài khoản, Moderator và phạm vi dự án. Hệ thống chỉ cho phép một Admin duy nhất.</p></div>
      <button v-if="isAdmin" class="primary" @click="createOpen=true"><UserPlus :size="18"/> Tạo người dùng</button>
    </header>
    <section class="toolbar" aria-label="Bộ lọc người dùng">
      <label class="search"><Search :size="18"/><input v-model="search" placeholder="Tìm theo tên hoặc email"/></label>
      <select v-model="role" aria-label="Lọc vai trò"><option value="">Mọi vai trò</option><option>Admin</option><option>Moderator</option><option>Member</option></select>
      <select v-model="status" aria-label="Lọc trạng thái"><option value="">Mọi trạng thái</option><option value="true">Đang hoạt động</option><option value="false">Đã khóa</option></select>
      <button class="icon-btn" title="Tải lại" @click="loadUsers"><RefreshCw :size="18"/></button>
    </section>
    <div v-if="loading" class="loading" aria-live="polite"><div v-for="i in 6" :key="i" class="skeleton"/></div>
    <div v-else-if="users.length" class="table-wrap"><table><thead><tr><th>Người dùng</th><th>Vai trò</th><th>Trạng thái</th><th>Sở hữu</th><th>Tham gia</th><th>Ngày tạo</th></tr></thead><tbody>
      <tr v-for="user in users" :key="user.id" tabindex="0" @click="selectUser(user)" @keydown.enter="selectUser(user)">
        <td><div class="user-cell"><span class="avatar">{{ user.fullName.slice(0,1).toUpperCase() }}</span><span><strong>{{ user.fullName }}</strong><small>{{ user.email }}</small></span></div></td>
        <td><span class="role" :data-role="user.role.toLowerCase()">{{ user.role }}</span></td><td><span class="status" :class="{inactive:!user.isActive}">{{ user.isActive?'Đang hoạt động':'Đã khóa' }}</span></td><td>{{ user.ownedProjectCount }}</td><td>{{ user.membershipProjectCount }}</td><td>{{ dateLabel(user.createdAt) }}</td>
      </tr></tbody></table></div>
    <section v-else class="empty"><UserRoundCog :size="36"/><h2>Không tìm thấy người dùng</h2><p>Thử thay đổi từ khóa hoặc bộ lọc.</p></section>
    <footer class="pagination"><span>{{ totalItems }} người dùng</span><div><button :disabled="page<=1" @click="page--">Trước</button><span>{{ page }} / {{ totalPages }}</span><button :disabled="page>=totalPages" @click="page++">Sau</button></div></footer>

    <div v-if="selected" class="overlay" @click.self="selected=null"><aside class="drawer" role="dialog" aria-modal="true" aria-label="Chi tiết người dùng">
      <button class="close" @click="selected=null"><X :size="20"/></button><div class="drawer-title"><span class="avatar large">{{ selected.fullName.slice(0,1).toUpperCase() }}</span><div><h2>{{ selected.fullName }}</h2><p>{{ selected.email }}</p></div></div>
      <div class="form-grid"><label>Họ tên<input v-model="selected.fullName" :disabled="!canEditSelected"/></label><label>Vai trò<select v-model="selected.role" :disabled="!isAdmin||selected.role==='Admin'"><option>Member</option><option>Moderator</option><option v-if="selected.role==='Admin'">Admin</option></select></label><label class="switch"><input v-model="selected.isActive" type="checkbox" :disabled="!canEditSelected"/> Tài khoản đang hoạt động</label></div>
      <div class="actions"><button class="primary" :disabled="saving||!canEditSelected" @click="saveUser">Lưu thay đổi</button><button class="secondary" :disabled="!canEditSelected" @click="revokeSessions"><LogOut :size="17"/> Thu hồi phiên</button><button v-if="isAdmin&&selected.role==='Moderator'" class="danger" :disabled="saving" @click="transferAdmin">Chuyển quyền Admin</button></div>
      <section class="projects"><h3><FolderKanban :size="18"/> Dự án của người dùng</h3><p v-if="projectsLoading">Đang tải dự án...</p><p v-else-if="!projects.length" class="muted">Người dùng chưa có dự án.</p><div v-for="project in projects" :key="project.id" class="project-row"><div><strong>{{ project.name }}</strong><small>{{ project.code }} · {{ project.taskCount }} nhiệm vụ</small></div><span v-if="project.isOwner" class="role" data-role="admin">Owner</span><select v-else :value="project.role" @change="updateProjectRole(project,($event.target as HTMLSelectElement).value)"><option v-for="item in ['Manager','ScrumMaster','Developer','Tester','Reviewer','Member','Viewer','Customer']" :key="item">{{ item }}</option></select></div></section>
    </aside></div>
    <div v-if="createOpen" class="overlay center" @click.self="createOpen=false"><form class="modal" @submit.prevent="createUser"><button type="button" class="close" @click="createOpen=false"><X :size="20"/></button><h2>Tạo người dùng</h2><p>Admin không thể được tạo từ biểu mẫu này.</p><label>Họ tên<input v-model="form.fullName" required/></label><label>Email<input v-model="form.email" type="email" required/></label><label>Mật khẩu tạm<input v-model="form.password" type="password" minlength="8" required/></label><label>Vai trò<select v-model="form.role"><option>Member</option><option>Moderator</option></select></label><button class="primary" :disabled="saving">Tạo tài khoản</button></form></div>
  </div>
</template>

<style scoped>
.admin-page{padding:32px;max-width:1440px;margin:auto;color:var(--text-primary,#162033)}.page-head{display:flex;justify-content:space-between;gap:24px;align-items:flex-end;margin-bottom:28px}.page-head h1{font-size:30px;margin:7px 0}.page-head p{margin:0;color:var(--text-secondary,#687386);max-width:720px}.kicker{display:inline-flex;align-items:center;gap:7px;color:#166534;font-weight:700;font-size:13px}.primary,.secondary,.danger,.icon-btn,.pagination button{display:inline-flex;align-items:center;justify-content:center;gap:8px;border-radius:10px;border:1px solid transparent;padding:10px 15px;font-weight:700;cursor:pointer}.primary{background:#166534;color:#fff}.secondary,.pagination button,.icon-btn{background:var(--surface,#fff);color:inherit;border-color:var(--border-color,#dce2ea)}.danger{background:#fff;color:#b91c1c;border-color:#fecaca}button:disabled{opacity:.45;cursor:not-allowed}.toolbar{display:grid;grid-template-columns:minmax(280px,1fr) 180px 180px 44px;gap:10px;margin-bottom:16px}.search{display:flex;align-items:center;gap:9px;padding:0 12px}.search,.toolbar select,.form-grid input,.form-grid select,.modal input,.modal select{height:44px;border:1px solid var(--border-color,#dce2ea);border-radius:10px;background:var(--surface,#fff);color:inherit}.search input{border:0;outline:0;background:transparent;width:100%;color:inherit}.toolbar select,.form-grid input,.form-grid select,.modal input,.modal select{padding:0 12px}.table-wrap{overflow:auto;border:1px solid var(--border-color,#dce2ea);border-radius:14px;background:var(--surface,#fff)}table{width:100%;border-collapse:collapse;min-width:850px}th,td{text-align:left;padding:14px 16px;border-bottom:1px solid var(--border-color,#e8edf3)}th{font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--text-secondary,#687386);background:var(--surface-muted,#f7f9fb)}tbody tr{cursor:pointer}tbody tr:hover,tbody tr:focus{background:rgba(22,101,52,.06);outline:none}.user-cell{display:flex;align-items:center;gap:11px}.user-cell span:last-child,.project-row div{display:grid;gap:3px}.user-cell small,.project-row small,.muted{color:var(--text-secondary,#687386)}.avatar{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;background:#dcfce7;color:#166534;font-weight:800}.avatar.large{width:52px;height:52px;font-size:20px}.role,.status{display:inline-flex;border-radius:999px;padding:5px 9px;font-size:12px;font-weight:700;background:#f1f5f9}.role[data-role=admin]{background:#dcfce7;color:#166534}.role[data-role=moderator]{background:#dbeafe;color:#1d4ed8}.status{color:#166534}.status.inactive{background:#fee2e2;color:#b91c1c}.pagination{display:flex;justify-content:space-between;align-items:center;padding:16px 2px}.pagination div{display:flex;align-items:center;gap:10px}.loading{display:grid;gap:8px}.skeleton{height:64px;border-radius:10px;background:linear-gradient(90deg,#edf1f5,#f8fafc,#edf1f5);background-size:200%;animation:pulse 1.4s infinite}.empty{text-align:center;padding:64px 20px;color:var(--text-secondary,#687386)}.overlay{position:fixed;inset:0;z-index:1000;background:rgba(15,23,42,.45);display:flex;justify-content:flex-end}.overlay.center{justify-content:center;align-items:center}.drawer,.modal{position:relative;background:var(--surface,#fff);color:inherit;width:min(560px,100%);height:100%;overflow:auto;padding:28px;box-shadow:-18px 0 50px rgba(15,23,42,.16)}.modal{width:min(460px,calc(100% - 32px));height:auto;border-radius:14px;display:grid;gap:15px}.modal label,.form-grid label{display:grid;gap:7px;font-weight:700;font-size:13px}.close{position:absolute;right:18px;top:18px;border:0;background:transparent;color:inherit;cursor:pointer}.drawer-title{display:flex;align-items:center;gap:14px;padding-right:42px;margin-bottom:28px}.drawer-title h2,.drawer-title p{margin:0}.form-grid{display:grid;grid-template-columns:1fr 180px;gap:16px}.switch{grid-column:1/-1;display:flex!important;align-items:center}.switch input{width:18px;height:18px}.actions{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0 30px}.projects{border-top:1px solid var(--border-color,#dce2ea);padding-top:22px}.projects h3{display:flex;align-items:center;gap:8px}.project-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 0;border-bottom:1px solid var(--border-color,#e8edf3)}.project-row select{height:36px;border:1px solid var(--border-color,#dce2ea);border-radius:8px;background:var(--surface,#fff);color:inherit}@keyframes pulse{to{background-position:-200%}}@media(max-width:760px){.admin-page{padding:20px 16px}.page-head{align-items:stretch;flex-direction:column}.toolbar{grid-template-columns:1fr 1fr}.search{grid-column:1/-1}.form-grid{grid-template-columns:1fr}.drawer{padding:22px}.actions{flex-direction:column}}@media(prefers-reduced-motion:reduce){.skeleton{animation:none}}
</style>
